def validate_transaction(node, cache=None):
    if cache is None:
        cache = {}

    if node is None:
        return 0
    if node in cache:
        return cache[node]

    result = 1 + validate_transaction(node.left, cache).get(node.left, 0) + validate_transaction(node.right, cache).get(node.right, 0)

    cache[node] = result
    return result
